package com.aistock.notification.alert;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import com.aistock.common.BusinessException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.flywaydb.core.Flyway;import java.time.*;import java.util.*;import java.util.concurrent.*;
@Tag("mysql") class AlertRuleMysqlTest {
 JdbcTemplate jdbc;AlertRuleService rules;UUID owner=UUID.randomUUID();Clock clock=Clock.fixed(Instant.parse("2026-10-10T00:00:00Z"),ZoneOffset.UTC);
 @BeforeEach void setup(){String url=System.getenv("MAIL_TEST_DB_URL"),pw=System.getenv("MAIL_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_notification_test?serverTimezone=UTC".equals(url)||pw==null)throw new IllegalStateException("isolated database required");jdbc=new JdbcTemplate(new DriverManagerDataSource(url,"root",pw));Flyway.configure().dataSource(jdbc.getDataSource()).load().migrate();rules=new AlertRuleService(new AlertRuleRepository(jdbc),id->new AlertRecords.Boundary(id,"baostock",UUID.randomUUID(),LocalDate.of(2026,10,9),LocalDate.of(2026,10,9),LocalDate.of(2026,10,9),"a".repeat(64),clock.instant(),"alert-boundary-v1"),clock,2);}
 AlertRecords.Create input(UUID request,String threshold){return new AlertRecords.Create(request,"SH600030","PRICE_ABOVE",threshold);}
 @Test void requestReplayAndConflictAndOwnerIsolation(){var req=UUID.randomUUID();var a=rules.create(owner,input(req,"26.000000"));assertEquals(a,rules.create(owner,input(req,"26.000000")));assertEquals(1,rules.list(owner,1,20).total());assertEquals("ALERT_REQUEST_CONFLICT",assertThrows(BusinessException.class,()->rules.create(owner,input(req,"27"))).code());assertEquals("RESOURCE_NOT_FOUND",assertThrows(BusinessException.class,()->rules.patch(UUID.randomUUID(),a.id(),new AlertRecords.Patch(0L,null,null,false))).code());}
 @Test void disableDoesNotDependOnMarketAndRevisionPreventsLostUpdate(){var a=rules.create(owner,input(UUID.randomUUID(),"26"));var unavailable=new AlertRuleService(new AlertRuleRepository(jdbc),id->{throw new IllegalStateException("offline");},clock,2);var off=unavailable.patch(owner,a.id(),new AlertRecords.Patch(0L,null,null,false));assertFalse(off.enabled());assertEquals(1,off.revision());assertEquals("ALERT_REVISION_CONFLICT",assertThrows(BusinessException.class,()->rules.patch(owner,a.id(),new AlertRecords.Patch(0L,null,null,true))).code());assertEquals(a.effectiveAfterTradeDate(),off.effectiveAfterTradeDate());}
 @Test void invalidDecimalAndPercentageRejected(){for(String s:List.of("NaN","Infinity","0","-1","1e2","1.0000001"))assertThrows(BusinessException.class,()->rules.create(owner,input(UUID.randomUUID(),s)));assertThrows(BusinessException.class,()->rules.create(owner,new AlertRecords.Create(UUID.randomUUID(),"SH600030","DAILY_RISE","100.0001")));}
 @Test void concurrentLimitCannotBeBypassed()throws Exception{var pool=Executors.newFixedThreadPool(4);try{var tasks=new ArrayList<Callable<Boolean>>();for(int i=0;i<4;i++)tasks.add(()->{try{rules.create(owner,input(UUID.randomUUID(),"26"));return true;}catch(BusinessException e){assertEquals("ALERT_LIMIT_REACHED",e.code());return false;}});int success=0;for(var r:pool.invokeAll(tasks))if(r.get())success++;assertEquals(2,success);assertEquals(2,rules.list(owner,1,20).total());}finally{pool.shutdownNow();}}
 @Test void evaluationAvailabilityFollowsConfigurationEvenForReplayedCreation(){UUID request=UUID.randomUUID();var input=input(request,"26");assertEquals("NOT_ENABLED",rules.create(owner,input).evaluationAvailability());var enabled=new AlertRuleService(new AlertRuleRepository(jdbc),id->{throw new IllegalStateException("unused");},clock,2,true);assertEquals("ENABLED",enabled.list(owner,1,20).items().get(0).evaluationAvailability());assertEquals("ENABLED",enabled.create(owner,input).evaluationAvailability());assertEquals("ENABLED",enabled.patch(owner,enabled.list(owner,1,20).items().get(0).id(),new AlertRecords.Patch(0L,null,null,false)).evaluationAvailability());assertEquals("NOT_ENABLED",new NotificationPreferenceService(new AlertRuleRepository(jdbc),clock).get(owner).deliveryAvailability());}
 @Test void preferencesDefaultOffAndUseRevision(){var p=new NotificationPreferenceService(new AlertRuleRepository(jdbc),clock);assertFalse(p.get(owner).emailEnabled());var on=p.patch(owner,0L,true,true);assertTrue(on.emailEnabled());assertEquals(1,on.revision());assertThrows(BusinessException.class,()->p.patch(owner,0L,false,true));assertThrows(BusinessException.class,()->p.patch(UUID.randomUUID(),0L,true,false));assertEquals(2,p.patch(owner,1L,false,true).revision());}
}
